"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[8321],{7995(e){e.exports=JSON.parse('{"title":"\uc624\ud508\uc18c\uc2a4 \uad00\ub9ac\uc790\ub85c \ubd80\ud130 \ubc30\uc6b8 \uc218 \uc788\ub294 \uc810","date":"2024-05-07","coverUrl":null,"html":"<h2 data-notion-block-id=\\"35e95bc9-114c-4463-ad51-9b7ff5bf97dd\\" id=\\"35e95bc9-114c-4463-ad51-9b7ff5bf97dd\\">\uc624\ud508\uc18c\uc2a4 \uad00\ub9ac\uc790\ub85c \ubd80\ud130 \ubc30\uc6b8 \uc218 \uc788\ub294 \uc810</h2><a href=\\"https://blog.stackblitz.com/posts/design-systems/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://blog.stackblitz.com/posts/design-systems/</a><p data-notion-block-id=\\"7402858f-c7ab-4bad-9685-09cde69569bf\\"><b>\uc2ec\uc724\uc12d</b>: \uc800\uc790\ub294 \ub514\uc790\uc778 \uc2dc\uc2a4\ud15c \uac1c\ubc1c\uc790\ub85c \ud55c\uc815\uc9c0\uc5c8\uc9c0\ub9cc DX\ub97c \uc704\ud574 \uacf5\uc6a9 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \ub9cc\ub4e4 \ub54c, \ud639\uc740 \uc0ac\ub0b4\uc5d0\uc11c\ub9cc \uc4f0\ub294 \uc0dd\uc0b0\uc131 \ud234\uc744 \ub9cc\ub4e4 \ub54c\ub3c4 \uc801\uc6a9\ub418\ub294 \uc774\uc57c\uae30\ub77c\uace0 \uc0dd\uac01\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc778\uc6d0\uc740 \uc801\uace0 \uc0ac\uc6a9\uc790 \ubd84\uc11d \ubc0f \uace0\ub3c4\ud654, \ubb38\uc11c\ud654, \ubaa9\ud45c\ub3c4 \uc7a1\uc544\uc57c \ud569\ub2c8\ub2e4. \ub2e4\ub978 \uc18c\uaddc\ubaa8 \ud300\ub3c4 \uac19\uc740 \ucc98\uc9c0\uc77c \uacbd\uc6b0\ub3c4 \uc788\uc8e0. \ucf54\ub529\uacfc \uad00\ub828\ub41c \ub0b4\uc6a9\uc740 \uc544\ub2c8\uc9c0\ub9cc \uc9c4\ud589\ud558\ub294 \uacfc\uc815, \uadf8\ub9ac\uace0 \uad00\ub9ac \uc2dc\uc2a4\ud15c\uc744 \uad6c\ucd95\ud558\ub294 \ubc29\ubc95\uc744 \uc5ff\ubd24\uc73c\uba74 \uc88b\uaca0\uc2b5\ub2c8\ub2e4!</p><h2 data-notion-block-id=\\"f141d899-2d6c-46b8-888f-be0cdeab6882\\" id=\\"f141d899-2d6c-46b8-888f-be0cdeab6882\\">React 16.8, \uadf8 \uc774\ud6c4</h2><a href=\\"https://tigerabrodi.blog/reacts-evolution-from-hooks-to-concurrent-react\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tigerabrodi.blog/reacts-evolution-from-hooks-to-concurrent-react</a><p data-notion-block-id=\\"6d4bdec7-9352-4220-bd92-4c900593f57e\\"><b>\uc2ec\uc724\uc12d</b>: React 16.8\uc758 hook\uc758 \ub3c4\uc785\ubd80\ud130\uc758 \uc5ed\uc0ac\ub97c \uc0b4\ud3b4\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. React 16.8 \uc774\ud6c4 \uad6c\uc870\ubd80\ud130 \uc2dc\uc791\ud574\uc11c \uc218\ub9ce\uc740 \ubb38\uc81c\ub97c \ud574\uacb0\ud588\uc2b5\ub2c8\ub2e4. \uc544\uc9c1 \ub9ac\uc561\ud2b8\uc758 \uacfc\uac70 \uc544\ud0a4\ud14d\ucc98\ub97c \ub9d0\ud558\ub294 \uae00\uc740 \ub0a8\uc544\uc788\uae30 \ub54c\ubb38\uc5d0 \uc774 \uae00\uc744 \uc77d\uace0 \ub098\uba74 React 18\uc774 \uc5b4\ub5bb\uac8c \ub9ce\uc740 \uae30\ub2a5\uc744 \ub2f4\uac8c \ub418\uc5c8\uc73c\uba70 React 18\uc758 \uae30\ub2a5\ub4e4\uc744 \uac70\uc758 \ub2e4 \uc628\uc804\ud558\uac8c \uc774\ud574\ud558\uc2e4 \uc218 \uc788\uc744\uac81\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"fbbf97c6-289b-4081-a48b-56fac37f7853\\" id=\\"fbbf97c6-289b-4081-a48b-56fac37f7853\\">HTMX\uc5d0 \ub300\ud55c \uc758\uacac\ub4e4</h2><a href=\\"https://konfigthis.com/blog/htmx/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://konfigthis.com/blog/htmx/</a><p data-notion-block-id=\\"55191b2e-9764-4c0d-a16d-c32fe40fb3dd\\"><b>\uc2ec\uc724\uc12d</b>: \uc0c8 \uae30\uc220\uc774 \ub4f1\uc7a5\ud558\uace0 \uadf8 \uae30\uc220\uc774 \uc774\ubaa9\uc744 \ub04c\uac8c \ub418\uba74(\ud2b9\ud788 \uc5b4\ub5a4 \uc0ac\ub78c\uc774 \uadf8 \uae30\uc220\uc744 \ucc2c\uc591\ud558\uace0 \uc774\uc804 \uae30\uc220\uc744 \ube44\ud558\ud558\ub294 \uc8fc\uc7a5\uc774 \ubcf4\uc774\uba74) \uc5ec\ub7ec \uc758\uacac\ub4e4\uc774 \ubcf4\uc774\uace0, \uadf8 \uc758\uacac\ub4e4\uc740 \ubaa8\ub450 \uc8fc\uad00\uc801\uc774\uae30 \ub54c\ubb38\uc5d0 \uac00\ub054 \uac00\ub2e4\uac00 \uadf8 \uae30\uc220\uc5d0 \ud729\uc4f8\ub9ac\uac70\ub098 \ud1a0\ub860\uc774 \uc774\ub8e8\uc5b4\uc9c0\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc800\uc790\ub294 \ub9ce\uc740 \ud1a0\ub860\uc744 \ud569\uc0b0\ud574 \uc790\uc2e0\uc758 \uc0dd\uac01\uacfc \ud568\uaed8 \uacf5\uac1c\ud588\uc2b5\ub2c8\ub2e4. \ubaa8\ub4e0 \uae30\uc220\uc774 \uadf8\ub807\ub4ef\uc774 \uc790\uc2e0\uc758 \uc870\uc9c1\uc758 \uc0c1\ud0dc\uc640 \ud604 \uc0c1\ud669\uc744 \ud30c\uc545\ud558\uace0 \ub3c4\uc785\ud574\uc57c \ud569\ub2c8\ub2e4 \ud83d\ude42(<a href=\\"https://ones-to-watch.ethansup.net/news/post/7a30f3669a2840449643c6c7f14270d8#ecfe89ce-2cee-43c7-be3c-f18300662445\\">\ub2f9\uc2e0\uc740 GraphQL\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4</a>, <a href=\\"https://danluu.com/simple-architectures/\\">\ub2e8\uc21c\ud55c \uc544\ud0a4\ud14d\ucc98 \ubc29\uc5b4\ud558\uae30</a>) </p><h2 data-notion-block-id=\\"20eb41a3-e451-4a08-a601-d39db6130be3\\" id=\\"20eb41a3-e451-4a08-a601-d39db6130be3\\">CSS vendor prefix\uc740 \uc544\uc9c1 \ud544\uc694\ud569\ub2c8\ub2e4.</h2><a href=\\"https://fullystacked.net/prefix/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://fullystacked.net/prefix/</a><p data-notion-block-id=\\"e914e760-725e-4893-849d-fe6c7b95dc58\\"><b>\uc2ec\uc724\uc12d</b>: \ube0c\ub77c\uc6b0\uc800\uc758 Interop \ud504\ub85c\uc81d\ud2b8\ub85c CSS vendor prefix\ub294 \uc4f0\uc9c0 \uc54a\uc544\ub3c4 \ub418\uc9c0\ub9cc \uc544\uc9c1 \uba87 \uac1c\uc758 \uc18d\uc131\uc740 \uc544\uc9c1 vendor prefix\uac00 \ud544\uc694\ud558\ub2e4\ub294 \uac83\uc744 \uc54c\ub9ac\ub294 \uae00\uc785\ub2c8\ub2e4. Interop\uc774 \ubb34\uc5c7\uc778\uc9c0 \uad81\uae08\ud558\uc2e0 \ubd84\uc740 <a href=\\"https://web.dev/blog/interop-2024?hl=ko\\">Interop 2024</a> \uae00\uc744 \ucc38\uace0\ud558\uc138\uc694!</p><h2 data-notion-block-id=\\"2a0146e6-32b6-4bd9-85c0-03b19ccf19e6\\" id=\\"2a0146e6-32b6-4bd9-85c0-03b19ccf19e6\\">Treeview \uad6c\uc870 UI\uc758 \ub4e4\uc5ec\uc4f0\uae30 \ubb38\uc81c</h2><a href=\\"https://ishadeed.com/article/tree-view-css-indent/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/tree-view-css-indent/</a><p data-notion-block-id=\\"063f7726-397b-4d2b-b7db-061bc16c1478\\">\ubb38\uc11c\ub97c \ud45c\ud604\ud560 \ub54c TreeView \uad6c\uc870\ub97c \ucc44\uc6a9\ud558\ub294\ub370, Github, Adobe, Figma\ub294 \uc5b4\ub5bb\uac8c CSS\ub97c \uc5b4\ub5bb\uac8c \uad6c\uc131\ud588\ub294\uc9c0 \ubd84\uc11d\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub2e4\ub978 \uc5b4\ub824\uc6b4 \uad6c\uc870\ub97c \ub2f9\uba74\ud588\uc744 \ub54c \ub2e4\ub978 \uacf3\uc740 \uc5b4\ub5bb\uac8c \uad6c\uc131\ud588\ub294\uc9c0 \ubcf4\ub294 \uac83\ub3c4 \uc88b\uc740 \uacf5\ubd80\uac00 \ub429\ub2c8\ub2e4 \ud83d\ude42</p><h2 data-notion-block-id=\\"447f4cf6-64e5-4a14-a011-35ca657dfd6b\\" id=\\"447f4cf6-64e5-4a14-a011-35ca657dfd6b\\">\uc5ec\ub7ec\uac00\uc9c0 \ucd9c\uc2dc \uc18c\uc2dd</h2><a href=\\"https://react.dev/blog/2024/04/25/react-19\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://react.dev/blog/2024/04/25/react-19</a><a href=\\"https://developer.mozilla.org/en-US/docs/Mozilla/Firefox/Releases/125\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://developer.mozilla.org/en-US/docs/Mozilla/Firefox/Releases/125</a><a href=\\"https://svelte.dev/blog/svelte-5-release-candidate\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://svelte.dev/blog/svelte-5-release-candidate</a><a href=\\"https://devblogs.microsoft.com/typescript/announcing-typescript-5-5-beta/#disabling-features-deprecated-in-typescript-50\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://devblogs.microsoft.com/typescript/announcing-typescript-5-5-beta/#disabling-features-deprecated-in-typescript-50</a><p data-notion-block-id=\\"bc00b9bf-9594-4eb8-9fbe-899ebe3e7d53\\">Form \uad00\ub828 \uae30\ub2a5\uacfc \uadf8\ub3d9\uc548 \ubd80\uc871\ud588\ub358 \uae30\ub2a5\uc744 \ubcf4\uc644\ud558\ub294 React 19 beta, \ud1a0\uc2a4\ud2b8 \uc54c\ub9bc, \uc561\uc158 \uba54\ub274\uac19\uc740 \uc0ac\uc6a9\uc790 \uc815\uc758 \uc694\uc18c\ub97c \uc704\ud55c Popover API, \ubd80\uc871\ud588\ub358 DX\ub97c \ub192\uc774\ub294 Svelte 5, \ubc84\uadf8\uc640 \uc2e0\uae30\ub2a5\uc758 \uc548\uc815\uc131\uc744 \ub192\uc778 TypeScript 5.5 beta\uc758 \ucd9c\uc2dc\ub97c \uc54c\ub838\uc2b5\ub2c8\ub2e4.</p>"}')}}]);